// One dumbbell or two — the member's own answer, recorded with the set.
//
// `getBellWeightInfo` (lib/workout/dumbbellWeight.ts) decides, PER EXERCISE,
// whether a dumbbell/kettlebell movement is conventionally loaded with a PAIR
// (`showTotal`) or with a single implement. That is a good default and a bad
// rule: Jon asked for the other half of it on 2026-09-18 — "there are some
// exercises that I can do single if I wanted to and just keep it as one 1
// dumbbell". The catalogue cannot know which, and before this nothing was
// recorded either way, so "50 with one dumbbell" and "50 with two" were the
// same row in history.
//
// This module is the override, and nothing more:
//
//   - `ISetLog.bells` (1 | 2) is OPTIONAL and carries NO default. Absent means
//     exactly what it has always meant: `getBellWeightInfo`'s automatic answer.
//     No existing set is migrated, and a member who ignores the control gets
//     the behaviour they had yesterday (`defaultBellCount` IS `showTotal`).
//   - The number the member types is still the load of ONE implement, raw and
//     never converted (the same rule NP-209 set for `weightUnit`). This field
//     says how many were in the hands, not what the weight means.
//   - Volume and PR maths DO NOT read it. They use the number typed and never
//     double it, both before and after this field existed. Whether one vs two
//     should count differently is an open question for George/Jon.
//
// Kept beside `dumbbellWeight.ts` rather than inside it on purpose: that file
// is mirrored verbatim into `@become/core` for the native app
// (webapp/tests/unit/nativeParity/trainingModules.test.ts holds the two copies
// to the same behaviour), and the native half of this feature is a separate
// ticket. Nothing here changes `getBellWeightInfo`'s answers.

import type { BellWeightInfo } from './dumbbellWeight'

/** How many implements were loaded for a set. Only ever one or two. */
export type BellCount = 1 | 2

/**
 * Read a member choice off untrusted input (a request body, a stored set, a
 * query answer). Returns `undefined` for anything that is not 1 or 2 — which
 * is the ABSENT case, i.e. "use the automatic answer", never a thrown error.
 * Numeric strings are accepted because JSON from older clients and form
 * values arrive that way.
 */
export function readBellCount(value: unknown): BellCount | undefined {
  const n = typeof value === 'string' ? Number(value) : value
  if (n === 1) return 1
  if (n === 2) return 2
  return undefined
}

/**
 * Today's automatic answer for an exercise: two when the catalogue says this
 * movement loads a simultaneous PAIR, one otherwise (a goblet hold, a carry,
 * single-arm/alternating work, and kettlebells unless the name says "double").
 * This is what an absent `bells` has always meant, and what the control is
 * defaulted to, so ignoring the control changes nothing.
 */
export function defaultBellCount(info: BellWeightInfo): BellCount {
  return info.showTotal ? 2 : 1
}

/**
 * The count to show for an exercise: the first usable candidate (the member's
 * choice this session, then the choice remembered from their most recent
 * logged set), falling back to `defaultBellCount`.
 */
export function resolveBellCount(info: BellWeightInfo, ...candidates: unknown[]): BellCount {
  for (const candidate of candidates) {
    const chosen = readBellCount(candidate)
    if (chosen) return chosen
  }
  return defaultBellCount(info)
}

/**
 * Whether the "= X total" hint under the weight input applies: only for a
 * dumbbell/kettlebell exercise being loaded with TWO. One implement moves the
 * number typed and nothing more, so the hint would overstate the load.
 */
export function showsBellTotal(info: BellWeightInfo, count: BellCount): boolean {
  return info.style !== null && count === 2
}

/** "DB" / "KB" — how the control labels the choice. */
export function bellCountLabel(info: BellWeightInfo, count: BellCount): string {
  const implement = info.style === 'kettlebell' ? 'KB' : 'DB'
  return `${count} ${implement}`
}

/**
 * The key an exercise's history is remembered under: its catalogue slug, or a
 * normalisation of its name for an exercise the catalogue does not know. The
 * same key `GET /api/workouts/last-performance` answers with, which is where
 * the remembered choice is read from — no new collection, no new model.
 */
export function bellMemoryKey(
  exercise: { exerciseSlug?: string; name?: string } | null | undefined,
): string {
  if (!exercise) return ''
  const slug = (exercise.exerciseSlug ?? '').trim().toLowerCase()
  if (slug) return slug
  return (exercise.name ?? '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
}

/**
 * The remembered choice per exercise, lifted out of a
 * `GET /api/workouts/last-performance` answer: `{ [memoryKey]: 1 | 2 }`.
 *
 * Keyed by the slug the request asked for, which IS `bellMemoryKey`. A slug
 * with no recorded answer (a legacy set, a barbell lift, no history at all) is
 * left OUT rather than defaulted, so the caller can fall back to the automatic
 * per-exercise answer and nothing invents a choice the member never made.
 */
export function bellsFromPerformances(
  performances: Record<string, { bells?: unknown } | null | undefined> | null | undefined,
): Record<string, BellCount> {
  const remembered: Record<string, BellCount> = {}
  for (const [key, performance] of Object.entries(performances ?? {})) {
    const bells = readBellCount(performance?.bells)
    if (bells) remembered[key] = bells
  }
  return remembered
}

/**
 * Server-side gate for the ONE field the client is allowed to send here:
 * every set keeps `bells` only when it is 1 or 2, and loses it otherwise.
 *
 * `bells` is the member's answer, so unlike `weightUnit` (stamped server-side,
 * never sent — NP-209) it does arrive in the request body. The Mongoose path
 * is an `enum`, so an out-of-range number would fail validation and take the
 * whole save down with it; dropping it instead leaves the set reading exactly
 * like a legacy one.
 *
 * Pure and generic over the caller's own set/exercise shapes, for the same
 * reason `stampWeightUnit` is: the two save paths in app/api/workouts/route.ts
 * must not lose a field some later reader needs.
 */
export function sanitizeBellCounts<
  S extends { bells?: BellCount },
  E extends { sets: S[] },
>(exercises: E[]): E[] {
  if (!Array.isArray(exercises)) return exercises
  return exercises.map((exercise) => {
    if (!exercise || !Array.isArray(exercise.sets)) return exercise
    return {
      ...exercise,
      sets: exercise.sets.map((set) => {
        if (!set || typeof set !== 'object') return set
        const next = { ...set }
        const bells = readBellCount((set as { bells?: unknown }).bells)
        if (bells) next.bells = bells
        else delete next.bells
        return next
      }),
    }
  }) as E[]
}
